do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'public can view global study documents temporarily') then
    create policy "public can view global study documents temporarily" on storage.objects for select to anon, authenticated using (bucket_id = 'global-study-russia-documents' and (storage.foldername(name))[1] = 'candidatures');
  end if;
end $$;
